// v2026.11.16-2 : Journal des pannes : mise à jour (toutes les 5 minutes)
// Lit la page de statut « homelab » de Uptime Kuma et note chaque appareil qui tombe (down) ou qui revient (up),
// avec l'heure exacte du battement Kuma. Le journal est gardé 30 jours dans la mémoire du workflow (static data).
// Rien à modifier ici, sauf l'adresse de Kuma si elle change.
const KUMA = 'http://IP_PRIVEE_4:PORT_3/api/status-page/';
const PAGE = 'homelab';
const JOURS_GARDES = 30;
const MAX_EVENEMENTS = 8000;
// Les battements d'avant cette heure sont ignorés (réglage du moniteur ISP le 16 nov. : fausses pannes)
const DEBUT_JOURNAL = Date.parse('2026-11-16T05:30:00-05:00');

const lire = async (chemin) => {
  const r = await this.helpers.httpRequest({ method: 'GET', url: KUMA + chemin, json: true, timeout: 20000 });
  return typeof r === 'string' ? JSON.parse(r) : r;
};

// Heure Kuma « 2026-11-16 08:54:12.123 » (UTC) en millisecondes
const temps = (s) => Date.parse(String(s).trim().replace(' ', 'T') + (/[zZ]|[+-]\d\d:?\d\d$/.test(s) ? '' : 'Z'));

const sd = $getWorkflowStaticData('global');
sd.dernier = sd.dernier || {};       // par moniteur : { t: dernier battement lu, etat: 'up' | 'down' }
sd.evenements = sd.evenements || []; // { t, id, nom, etat }
sd.noms = sd.noms || {};

const [info, hb] = await Promise.all([lire(PAGE), lire('heartbeat/' + PAGE)]);
(info.publicGroupList || []).forEach((g) => (g.monitorList || []).forEach((m) => { sd.noms[String(m.id)] = m.name; }));
const listes = (hb && hb.heartbeatList) || {};

let ajoutes = 0;
Object.keys(listes).forEach((id) => {
  const nom = sd.noms[id] || ('Moniteur ' + id);
  const d = sd.dernier[id] || { t: 0, etat: null };
  const battements = (listes[id] || [])
    .map((b) => ({ t: temps(b.time), s: b.status }))
    .filter((b) => !isNaN(b.t) && b.t > d.t && b.t >= DEBUT_JOURNAL && (b.s === 0 || b.s === 1))   // 2 = en attente, 3 = maintenance : ignorés
    .sort((a, b) => a.t - b.t);
  battements.forEach((b) => {
    const etat = b.s === 1 ? 'up' : 'down';
    // Premier battement jamais lu : on ne note qu'une panne déjà en cours
    if (d.etat === null ? etat === 'down' : etat !== d.etat) {
      sd.evenements.push({ t: b.t, id: id, nom: nom, etat: etat });
      ajoutes++;
    }
    d.etat = etat;
    d.t = b.t;
  });
  sd.dernier[id] = d;
});

// Ménage : 30 jours au plus
const limite = Date.now() - JOURS_GARDES * 24 * 3600 * 1000;
sd.evenements = sd.evenements.filter((e) => e.t >= limite).sort((a, b) => a.t - b.t).slice(-MAX_EVENEMENTS);
sd.maj = Date.now();

return [{ json: { ok: true, evenements_ajoutes: ajoutes, evenements_gardes: sd.evenements.length, maj: new Date(sd.maj).toISOString() } }];

// v2026.11.23-1 : moniteurs qui dépendent d'un autre : « pfSense règles » interroge Loki (CT 110 sur proxmox2) ;
//   s'il tombe en même temps que Loki ou Proxmox2, ce n'est pas une erreur de règles mais une conséquence, et la cause
//   devient Proxmox2 (serveur ou lien réseau) ou Loki (le 22 nov., le câble réseau de proxmox2 accusait « pfSense règles »)
// v2026.11.21-2 : cause probable corrigée quand pfSense tombe : Kuma (sur TrueNAS, VLAN20) joint les switchs, le modem,
//   l'ISP et NordVPN à travers pfSense ; s'ils reviennent en même temps que lui (3 min de marge), ce sont des conséquences
//   et la cause est pfSense (le 21 nov., le redémarrage de pfSense après sa mise à jour accusait le switch USW Pro Max-2)
// v2026.11.17-7 : maillon NordVPN = moniteur « NordVPN (tunnel) » (l'ancien « NordVPN Server » reste reconnu pour l'historique)
// v2026.11.16-2 : Journal des pannes : lecture (appelé par la page Réseau, relais Nginx /journal-pannes/)
// Regroupe les événements en pannes : une panne commence quand un appareil tombe et finit quand tous sont revenus.
// Pour chaque panne : l'ordre dans lequel les appareils sont tombés et revenus, et la cause probable.
const sd = $getWorkflowStaticData('global');
const evenements = (sd.evenements || []).slice().sort((a, b) => a.t - b.t);

// Chaîne Internet, du bas (chez toi) vers le haut (Internet) : le maillon le plus bas tombé est la cause
const CHAINE = [
  { motif: /pro\s*max\s*-?\s*2\b/i, cause: 'le switch USW Pro Max-2 (réseau local)' },
  { motif: /pro\s*max\s*-?\s*1\b/i, cause: 'le switch USW Pro Max-1 (réseau local)' },
  { motif: /^\s*pf\s*sense\s*$/i, cause: 'le pare-feu pfSense' },
  { motif: /modem/i, cause: 'le modem ISP (ou le câble)' },
  { motif: /isp/i, cause: 'le fournisseur Internet (réseau ISP)' },
  { motif: /nordvpn|server\s*vpn/i, cause: 'NordVPN : le tunnel de pfSense est coupé (Internet fonctionne)' },
];
const rang = (nom) => CHAINE.findIndex((m) => m.motif.test(nom || ''));
const RANG_PFSENSE = 2;

// Kuma tourne sur TrueNAS (VLAN20) : pour joindre les switchs (IP_PRIVEE), le modem, et l'API de pfSense (ISP, NordVPN),
// il passe par pfSense. Quand pfSense tombe, ces moniteurs tombent aussi, même si les appareils fonctionnent.
// Un appareil de la chaîne qui revient au plus tard 3 minutes après pfSense est donc une conséquence de pfSense.
const MARGE_RETOUR_MS = 3 * 60 * 1000;
const CAUSE_PFSENSE = 'le pare-feu pfSense (redémarrage ou panne) : les switchs, le modem, le fournisseur (ISP) et NordVPN sont vus à travers lui';

const pannes = [];
const enPanne = new Map();   // id -> nom
let p = null;
evenements.forEach((e) => {
  if (e.etat === 'down' && !enPanne.has(e.id)) {
    if (!p) { p = { debut: e.t, fin: null, appareils: [] }; pannes.push(p); }
    enPanne.set(e.id, e.nom);
    p.appareils.push({ nom: e.nom, tombe: e.t, revenu: null });
  } else if (e.etat === 'up' && enPanne.has(e.id)) {
    enPanne.delete(e.id);
    if (p) {
      const a = p.appareils.slice().reverse().find((x) => x.nom === e.nom && x.revenu === null);
      if (a) a.revenu = e.t;
      if (!enPanne.size) { p.fin = e.t; p = null; }
    }
  }
});

// Vrai si la chute de cet appareil s'explique par celle de pfSense (tombé pendant que pfSense était tombé, revenu avec lui)
function expliqueParPfsense(a, pf) {
  if (!pf || a === pf) return false;
  const pfRevenu = pf.revenu === null ? Infinity : pf.revenu;
  if (a.tombe > pfRevenu) return false;                       // tombé après le retour de pfSense
  if (a.revenu === null) return pf.revenu === null;           // toujours en panne : seulement si pfSense l'est aussi
  return a.revenu <= pfRevenu + MARGE_RETOUR_MS;
}

// Moniteurs qui dépendent d'un autre : s'ils tombent dans la même panne que leur source, ce sont des conséquences.
// L'ordre compte : la première source tombée de la liste devient la cause (Proxmox2 avant Loki, car Loki tourne sur proxmox2).
const DEPENDANCES = [
  {
    motif: /pf\s*sense\s*r[eè]gles?/i,
    sources: [
      { motif: /^\s*proxmox\s*-?\s*2\s*$/i, cause: 'Proxmox2 ne répondait plus (serveur ou lien réseau) : Loki tourne dessus (CT 110), et le moniteur pfSense règles interroge Loki' },
      { motif: /loki/i, cause: 'Loki injoignable : le moniteur pfSense règles interroge Loki, les règles de pfSense ne sont pas en cause' },
    ],
  },
  {
    motif: /loki/i,
    sources: [
      { motif: /^\s*proxmox\s*-?\s*2\s*$/i, cause: 'Proxmox2 ne répondait plus (serveur ou lien réseau) : Loki tourne dessus (CT 110)' },
    ],
  },
];
// Vrai si l'appareil a est tombé pendant que l'appareil s était tombé (même panne, périodes qui se chevauchent)
function chevauche(a, s) {
  const finA = a.revenu === null ? Infinity : a.revenu;
  const finS = s.revenu === null ? Infinity : s.revenu;
  return a.tombe <= finS + MARGE_RETOUR_MS && s.tombe <= finA + MARGE_RETOUR_MS;
}
// Source tombée qui explique la chute de a (ou null)
function sourceDe(a, appareils) {
  const dep = DEPENDANCES.find((d) => d.motif.test(a.nom || ''));
  if (!dep) return null;
  for (const src of dep.sources) {
    const s = appareils.find((x) => x !== a && src.motif.test(x.nom || '') && chevauche(a, x));
    if (s) return { appareil: s, cause: src.cause };
  }
  return null;
}

const iso = (t) => (t ? new Date(t).toISOString() : null);
const resultat = pannes.reverse().map((x) => {
  // Cause : le maillon de la chaîne le plus bas parmi les appareils tombés, sans ceux qu'explique la chute de pfSense ;
  // sinon le premier appareil tombé
  const pf = x.appareils.find((a) => rang(a.nom) === RANG_PFSENSE) || null;
  const dansChaine = x.appareils
    .filter((a) => rang(a.nom) >= 0 && !expliqueParPfsense(a, pf))
    .sort((a, b) => rang(a.nom) - rang(b.nom));
  let cause;
  if (dansChaine.length) {
    const c = dansChaine[0];
    cause = { nom: c.nom, texte: rang(c.nom) === RANG_PFSENSE ? CAUSE_PFSENSE : CHAINE[rang(c.nom)].cause };
  } else {
    // Hors de la chaîne Internet : un moniteur qui dépend d'un autre tombé en même temps n'est pas la cause
    const libres = x.appareils.filter((a) => !sourceDe(a, x.appareils));
    const dep = x.appareils.map((a) => sourceDe(a, x.appareils)).find(Boolean);
    const premier = libres[0] || x.appareils[0];
    if (dep && premier === dep.appareil) {
      cause = { nom: premier.nom, texte: dep.cause };
    } else if (/pf\s*sense\s*r[eè]gles?/i.test(premier.nom || '')) {
      cause = { nom: premier.nom, texte: "pfSense refuse ses règles de pare-feu (« error(s) loading the rules ») : Firewall, pfBlockerNG, Update, Force Reload All, puis vérifier avec pfctl -nf /tmp/rules.debug" };
    } else {
      cause = { nom: premier.nom, texte: premier.nom + ' ne répondait plus' };
    }
  }
  return {
    debut: iso(x.debut),
    fin: iso(x.fin),
    duree_min: Math.max(1, Math.round(((x.fin || Date.now()) - x.debut) / 60000)),
    en_cours: !x.fin,
    cause: cause,
    ordre: x.appareils.map((a) => ({ nom: a.nom, tombe: iso(a.tombe), revenu: iso(a.revenu) })),
  };
});

return [{
  json: {
    maj: iso(sd.maj),
    depuis: iso(evenements.length ? evenements[0].t : sd.maj),
    nb_pannes: resultat.length,
    pannes: resultat.slice(0, 50),
  },
}];
